export const BODY: string = "\n<p>چمک سب سے آسان تصویر درست ہے، اور وہ جسے لوگ پہلے اٹھاتے ہیں۔ گہری تصویر نظر آنے لگتی ہے، دھلی ہوئی تصویر گہرائی پاتی ہے، اور پھیکی تصویر واپس زندہ ہو جاتی ہے۔</p>\n<p>مگر چمک کو زیادہ کرنا آسان ہے۔ اسے بہت آگے دھکیلیں تو تصویر چپٹی اور سرمئی ہو جاتی ہے، روشن حصوں میں کوئی تفصیل باقی نہیں رہتی۔</p>\n<p>یہ رہنما بتاتا ہے کہ چمک کیسے کام کرتی ہے، سلائیڈر اور پری سیٹ اچھی طرح کیسے استعمال کریں، اور گہری تصویریں انہیں برباد کیے بغیر کیسے درست کریں۔ اس میں پورٹریٹ، منظر، اسکرین شاٹ، اور وہ غلطیاں شامل ہیں جو اچھی تصویر خراب کرتی ہیں۔ مفت <a href=\"/ur/tasveer-ki-brightness-badlein/\">Image Brightness Editor</a> آپ کو وہ سلائیڈر اور پری سیٹ آپ کے براؤزر میں دیتا ہے، تاکہ آپ سیکنڈوں میں گہری تصویر بچا سکیں۔</p>\n<h2 id=\"what-brightness-does\">چمک دراصل کیا کرتی ہے</h2>\n<p>چمک تصویر کے ہر پکسل کو سفید کی طرف یا کالے کی طرف منتقل کرتی ہے۔ اسے بڑھانے سے گہرے حصے ہلکے اور ہلکے حصے اور بھی ہلکے ہو جاتے ہیں، جبکہ اسے کم کرنے سے سب کچھ گہرا ہو جاتا ہے۔</p>\n<p>تبدیلی پوری تصویر میں یکساں ہے۔ چمک ایڈجسٹمنٹ سائے یا جھلکیاں نہیں چنتی؛ یہ پوری لہجہ حد کو ایک ساتھ اوپر یا نیچے منتقل کرتی ہے۔</p>\n<p>یہ یکسانیت چمک کی طاقت اور کمزوری دونوں ہے۔ یہ مجموعی طور پر گہری یا ہلکی تصویر درست کرنے کا تیز ترین طریقہ ہے، مگر یہ ایسی تصویر درست نہیں کر سکتی جو ایک حصے میں گہری اور دوسرے میں روشن ہو۔</p>\n<h2 id=\"why-photos-are-dark\">تصویریں گہری کیوں نکلتی ہیں</h2>\n<p>فون کیمرے مشکل روشنی میں اکثر کم نمائش کرتے ہیں۔ شخص کے پیچھے روشن آسمان، پس منظر میں کھڑکی، یا مضبوط روشنی ماخذ کیمرے کو دھوکہ دے کر موضوع کو گہرا کر سکتا ہے۔</p>\n<p>اندرونی تصویریں آسان وجہ سے گہری ہیں: روشنی کافی نہیں۔ ایک بلب سے روشن کمرہ کیمرے کو باہر کے منظر سے کہیں کم روشنی دیتا ہے، اور تصویر یہ دکھاتی ہے۔</p>\n<p>اسکین شدہ دستاویزات اور پرانی تصویریں بھی اکثر گہری ہیں۔ عمر پرنٹ کو دھندلا کرتی ہے، اسکینر لہجے غلط پڑھتے ہیں، اور نتیجہ سرمئی، دھندلی تصویر ہے جسے روشن کرنا چاہیے۔</p>\n<h2 id=\"brightening-vs-exposure\">روشن کرنا بمقابلہ نمائش: کیا وہ ایک جیسے ہیں؟</h2>\n<p>چمک اور نمائش متعلقہ ہیں مگر ایک جیسی نہیں۔ نمائش بدلتی ہے کہ کیمرے نے کتنی روشنی پکڑی، جبکہ چمک بدلتی ہے کہ پکڑے گئے پکسل کیسے دکھائے جاتے ہیں۔</p>\n<p>ایڈیٹر میں دونوں کنٹرول اکثر ایک جیسے لگتے ہیں، کیونکہ دونوں تصویر کو ہلکا یا گہرا بناتے ہیں۔ فرق یہ ہے کہ وہ لہجہ حد کے انتہاؤں کو کیسے سنبھالتے ہیں۔</p>\n<p>نمائش ایڈجسٹمنٹ جھلکیوں اور سائے کو مختلف طریقے سے متاثر کرتی ہیں، کناروں پر زیادہ تفصیل محفوظ رکھتے ہوئے۔ چمک سب کچھ برابر منتقل کرتی ہے، جو روشن حصوں کو تیز دھو سکتی ہے۔</p>\n<h2 id=\"slider-explained\">چمک سلائیڈر، وضاحت</h2>\n<p>چمک سلائیڈر منفی سے مثبت قیمتوں تک چلتا ہے، صفر کا مطلب کوئی تبدیلی نہیں۔ اسے دائیں منتقل کرنے سے تصویر روشن ہوتی ہے، اور بائیں منتقل کرنے سے گہری ہوتی ہے۔</p>\n<p>چھوٹی حرکتیں بڑا فرق ڈالتی ہیں۔ 10 سے 15 فیصد کی تبدیلی اکثر گہری تصویر درست کرنے کے لیے کافی ہے، اور بڑی حرکتیں جلد جھلکیاں دھو دیتی ہیں۔</p>\n<p>ٹول اپ لوڈ کے فوراً بعد آپ کی تصویر کو پلس 15 فیصد پر پیش نظارہ دکھاتا ہے۔ وہ نقطہ آغاز آپ کو فوری احساس دیتا ہے کہ معتدل روشن کرنا کیسا لگتا ہے۔</p>\n<h2 id=\"quick-presets\">ایک کلک درست کے لیے فوری پری سیٹ</h2>\n<p>ٹول میں فوری پری سیٹ ہیں جو عام چمک قیمتیں ایک کلک میں لگاتے ہیں۔ وہ سلائیڈر گھسیٹے بغیر مختلف سطحیں آزمانے کا تیز طریقہ ہیں۔</p>\n<p>پری سیٹ نقطہ آغاز ہیں، حتمی جواب نہیں۔ ایک کلک کریں، پیش نظارہ دیکھیں، اور پھر سلائیڈر سے باریک کریں اگر نتیجہ قریب مگر بالکل درست نہ ہو۔</p>\n<p>اختیارات تیزی سے موازنہ کرنے کے لیے پری سیٹ استعمال کریں۔ پلس 15 فیصد والا پری سیٹ پلس 30 فیصد والے کے ساتھ دکھاتا ہے کہ تصویر دھونے سے پہلے کتنی روشنائی برداشت کر سکتی ہے۔</p>\n<h2 id=\"compare-modes\">موازنہ موڈ: پہلے، بعد، اور تقسیم</h2>\n<p>موازنہ موڈ آپ کو اصل اور ترمیم شدہ ورژن ایک ساتھ دکھاتے ہیں۔ After منظر روشن شدہ تصویر دکھاتا ہے، Before منظر اصل دکھاتا ہے، اور Split منظر دونوں کو ساتھ ساتھ دکھاتا ہے۔</p>\n<p>Split موازنہ چمک کام کے لیے سب سے مفید ہے۔ یہ آپ کو بالکل دیکھنے دیتا ہے کہ کون سے حصے بہتر ہوئے اور کون سے دھل گئے، دونوں ورژن کے درمیان واضح لکیر کے ساتھ۔</p>\n<p>مکمل اسکرین موازنہ آپ کو سب سے بڑا منظر دیتا ہے۔ یہ روشن شدہ تصویر پرکھنے کا بہترین طریقہ ہے، کیونکہ مکمل سائز تصویر وہ تفصیل دکھاتی ہے جو چھوٹا پیش نظارہ چھپاتا ہے۔</p>\n<h2 id=\"brightening-portraits\">پورٹریٹ روشن کرنا</h2>\n<p>پورٹریٹ کو نرم روشن کرنا چاہیے۔ بہت گہرا چہرہ آنکھیں اور تاثر چھپاتا ہے، مگر بہت روشن چہرہ جلد بناوٹ کھو دیتا ہے اور چپٹا لگتا ہے۔</p>\n<p>10 سے 15 فیصد کے چھوٹے اضافے سے شروع کریں اور جلد لہجے جانچیں۔ چہرہ قدرتی روشن لگنا چاہیے، ایسا نہیں جیسے قریب سے فلیش چلا ہو۔</p>\n<p>پیشانی اور ناک پر جھلکیاں دیکھیں۔ وہ حصے پہلے پھٹتے ہیں، اور چہرے پر سفید دھبوں والا روشن پورٹریٹ گہرے پورٹریٹ سے بدتر لگتا ہے۔</p>\n<h2 id=\"brightening-landscapes\">منظر روشن کرنا</h2>\n<p>منظر کو اکثر سائے میں روشن کرنا چاہیے جبکہ آسمان روشن رہتا ہے۔ یکساں چمک اضافہ سامنے والا حصہ درست کرتے ہوئے آسمان دھو سکتا ہے۔</p>\n<p>معتدل اضافہ استعمال کریں اور پہلے آسمان جانچیں۔ اگر بادل اپنی شکل کھو کر سفید خالی بن جائیں تو آپ بہت آگے جا چکے ہیں۔</p>\n<p>گہرے سامنے اور روشن آسمان والے منظر کے لیے نرم روشن کریں اور کچھ سمجھوتا قبول کریں۔ مقصد متوازن تصویر ہے، مکمل نہیں۔</p>\n<h2 id=\"brightening-screenshots\">اسکرین شاٹ اور دستاویز روشن کرنا</h2>\n<p>اسکرین شاٹ اور اسکین شدہ دستاویز کو تصویروں سے زیادہ جارحانہ روشن کرنا چاہیے۔ متن پڑھنے کے قابل ہونا چاہیے، اور سرمئی متن والا گہرا اسکین بیکار ہے۔</p>\n<p>محفوظ کرنے والا مرحلہ چھوڑنے کے لیے اسکرین شاٹ Ctrl+V سے سیدھا چسپاں کریں۔ تصویر فوراً ایڈیٹر میں دکھائی دیتی ہے، روشن کرنے کے لیے تیار۔</p>\n<p>چمک بڑھائیں جب تک متن واضح نہ ہو اور پس منظر سفید نہ ہو۔ صاف سفید پس منظر اور گہرے متن والی دستاویز پڑھنا اور پرنٹ کرنا آسان ہے۔</p>\n<h2 id=\"darkening-photos\">روشن کرنے کی بجائے گہرا کب کریں</h2>\n<p>گہرا کرنا اس وقت مفید ہے جب تصویر زیادہ نمائش والی ہو۔ روشن، دھلی ہوئی تصویر جس میں کوئی سائے نہ ہوں، اسے گہرائی اور تضاد واپس لانے کے لیے منفی چمک چاہیے۔</p>\n<p>بہت روشن تصویر کے لیے مائنس 15 یا مائنس 30 فیصد جیسی منفی قیمتیں استعمال کریں۔ سائے گہرے ہوتے ہیں، رنگ دولت پاتے ہیں، اور تصویر زیادہ ٹھوس لگتی ہے۔</p>\n<p>گہرا کرنا اس وقت بھی مدد کرتا ہے جب تصویر متن کے پیچھے بیٹھے گی۔ گہری تصویر سفید متن کو پڑھنے کے قابل بناتی ہے، جو سلائیڈ، پوسٹر اور سوشل گرافکس کے لیے مفید ہے۔</p>\n<h2 id=\"noise-and-quality\">شور، کوالٹی، اور روشن کرنے کی حدیں</h2>\n<p>روشن کرنا شور ظاہر کرتا ہے۔ گہری تصویر اپنا دانہ سائے میں چھپاتی ہے، اور چمک اٹھانے سے وہ دانہ دھبے والی بناوٹ کے طور پر نظر آتا ہے۔</p>\n<p>JPEG کمپریشن مسئلہ بدتر بناتی ہے۔ گہری، کمپریس شدہ JPEG مضبوط روشن کرنے پر ہلکے بلاک نمونے دکھاتی ہے، کیونکہ کمپریشن خامیاں نظر آنے لگتی ہیں۔</p>\n<p>حل یہ ہے کہ نرم روشن کریں اور اپنے پاس بہترین اصل سے شروع کریں۔ اچھی روشنی میں لی گئی تصویر کو کم روشن کرنا چاہیے، اور کم روشن کرنے کا مطلب کم شور ہے۔</p>\n<h2 id=\"formats-and-export\">فارمیٹ اور برآمد</h2>\n<p>ٹول عام تصویر فارمیٹ قبول کرتا ہے، بشمول JPG، PNG، WebP اور HEIC، 20 MB تک فائلیں۔ آپ اپنی ضرورت کے حساب سے JPG، PNG یا WebP کے طور پر برآمد کر سکتے ہیں۔</p>\n<p>PNG یا WebP کے طور پر برآمد کرنے سے بنیادی تصویر میں شفافیت محفوظ رہتی ہے۔ اگر آپ کا ماخذ شفاف PNG گرافک ہے تو روشن برآمد دیکھنے والے حصے برقرار رکھتی ہے۔</p>\n<p>تصویروں کے لیے اعلیٰ کوالٹی ترتیب پر JPG اچھا کام کرتا ہے۔ روشن کرنا فائل سائز میں زیادہ نہیں بڑھاتا، اس لیے برآمد اصل وزن کے قریب رہتی ہے۔</p>\n<h2 id=\"brightness-and-contrast\">چمک اور تضاد ایک ساتھ کام کرتے ہیں</h2>\n<p>چمک اور تضاد ساتھی ہیں۔ چمک پوری لہجہ حد کو اوپر یا نیچے منتقل کرتی ہے، جبکہ تضاد گہرے اور ہلکے سروں کے درمیان فاصلہ کھینچتا یا نچوڑتا ہے۔</p>\n<p>گہری اور چپٹی تصویر کو دونوں ایڈجسٹمنٹ چاہییں۔ پہلے روشن کریں تاکہ مجموعی سطح اٹھے، پھر تضاد شامل کریں تاکہ وہ گہرائی بحال ہو جو روشن کرنے سے دھل گئی۔</p>\n<p>جب تصویر روشن کرنے کے بعد سرمئی اور بے جان لگے تو <a href=\"/ur/tasveer-ka-contrast-badlein/\">Image Contrast Editor</a> استعمال کریں۔ چھوٹا تضاد اضافہ سائے اور جھلکیاں واپس لاتا ہے۔</p>\n<h2 id=\"privacy-local-processing\">رازداری: اپ لوڈ کیے بغیر ترمیم</h2>\n<p>تمام چمک ترمیم آپ کے براؤزر میں ہوتی ہے۔ آپ کی تصویریں کبھی سرور پر اپ لوڈ نہیں ہوتیں، جو اہم ہے جب تصویریں ذاتی ہوں، خاندانی تصویریں ہوں، یا کلائنٹ کام ہو۔</p>\n<p>یہ کلاؤڈ ایڈیٹر پر حقیقی فائدہ ہے۔ خاندانی تصویر یا نجی دستاویز کو صرف روشن کرنے کے لیے ایسے سرور پر نہیں جانا چاہیے جسے آپ دیکھ نہیں سکتے۔</p>\n<p>ٹول برآمد پر EXIF GPS ڈیٹا بھی ہٹاتا ہے۔ ٹول سے ڈاؤن لوڈ شدہ روشن تصویر میں کوئی ریکارڈ نہیں کہ وہ کہاں لی گئی تھی۔</p>\n<h2 id=\"common-mistakes\">چمک ایڈجسٹ کرتے ہوئے عام غلطیاں</h2>\n<p>سب سے عام غلطی بہت زیادہ روشن کرنا ہے۔ پلس 50 یا پلس 100 فیصد تک دھکیلی گئی تصویر اپنی جھلکیاں مکمل کھو دیتی ہے، اور نتیجہ بغیر تفصیل والی چپٹی، سفید تصویر ہے۔</p>\n<p>دوسری غلطی پہلے سے روشن تصویر کو روشن کرنا ہے۔ زیادہ نمائش والی تصویر کو گہرا کرنا چاہیے، روشن نہیں، اور مزید روشنی شامل کرنے سے وہ صرف بدتر ہوتی ہے۔</p>\n<p>لوگ جھلکیاں جانچنا بھی بھول جاتے ہیں۔ چھوٹے پیش نظارے میں ٹھیک لگنے والا چہرہ یا آسمان مکمل سائز پر پھٹا ہو سکتا ہے، اس لیے نتیجہ ہمیشہ بڑا جانچیں۔</p>\n<h2 id=\"brightness-workflow\">صاف چمک ترمیم کا ورک فلو</h2>\n<p>اصل فائل سے شروع کریں اور فیصلہ کریں کہ اسے کتنی روشنائی چاہیے۔ تھوڑی گہری تصویر کو 10 سے 15 فیصد چاہیے، جبکہ بہت گہری کو 30 فیصد یا زیادہ چاہیے ہو سکتی ہے۔</p>\n<p>چمک لگائیں، پھر موازنہ منظر جانچیں۔ تقسیم منظر بالکل دکھاتا ہے کہ کون سے حصے بہتر ہوئے اور کون سے دھل گئے۔</p>\n<p>اگر روشن کرنے کے بعد تصویر چپٹی لگے تو تضاد شامل کریں۔ چھوٹا تضاد اضافہ وہ گہرائی بحال کرتا ہے جسے چمک اضافہ دھو سکتا ہے۔</p>\n<h2 id=\"brightening-for-social\">سوشل میڈیا کے لیے تصویریں روشن کرنا</h2>\n<p>سوشل فیڈ روشن، صاف تصویروں کو پسند کرتی ہیں۔ گہری تصویر اسکرول ہو جاتی ہے، جبکہ اچھی روشن تصویر انگوٹھا روکتی ہے اور دوسری نظر پاتی ہے۔</p>\n<p>سوشل تصویریں پرنٹ کے مقابلے میں تھوڑی زیادہ روشن کریں۔ اسکرینیں چمک میں مختلف ہیں، اور آپ کے فون پر ٹھیک لگنے والی تصویر کسی اور کے فون پر گہری لگ سکتی ہے۔</p>\n<p>روشن کرنا قدرتی رکھیں۔ بہت آگے دھکیلی گئی تصویر مصنوعی لگتی ہے، اور فالوور بتا سکتے ہیں جب روشنی منظر سے میل نہ کھائے۔</p>\n<p>قدم بہ قدم عمل کے لیے <a href=\"/ur/blog/tasveer-ki-brightness-kaise-badlein/\">How to Adjust Image Brightness</a> دیکھیں۔ موازنہ کے لیے <a href=\"/ur/blog/brightness-vs-exposure-vs-contrast/\">Brightness vs Exposure vs Contrast: Editing Basics</a> پڑھیں، اور روشن کرنے کے بعد چپٹے تضاد کو درست کرنے کے لیے <a href=\"/ur/tasveer-ka-contrast-badlein/\">Image Contrast Editor</a> آزمائیں۔</p>\n";

